PARAM1 = " + Test_Variable + @"
PARAM2(1) = 6 FT
END
ALIAS
PARAM1 AS ALIAS PARAM
END
INITIATORS
INIT1 = T
INIT2 = 0
END
WHEN TIM >= " + Test_Variable + @"
